const CACHE='hansang-shell-v2';
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);const response=await fetch('/',{cache:'reload'});if(!response.ok)throw new Error('App shell unavailable');const html=await response.text();await cache.put('/',new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8'}}));const assets=[...html.matchAll(/(?:src|href)=["']([^"']+\.(?:js|css))["']/g)].map(m=>m[1]);await cache.addAll(['/icon.svg','/manifest.webmanifest',...assets]);await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==location.origin||u.pathname.startsWith('/api/'))return;event.respondWith(fetch(event.request).then(res=>{if(res.ok){const copy=res.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return res;}).catch(()=>caches.match(event.request).then(c=>c||(event.request.mode==='navigate'?caches.match('/'):Response.error()))));});
